import gzip
import json
import unittest

from solution import decode_contacts


def packed(text):
    return gzip.compress(text.encode('utf-8'), mtime=0)


class DecodeContactsTests(unittest.TestCase):
    def test_valid_lines_order_extra_fields_and_html_escaping(self):
        first = packed(
            json.dumps({'label': 'A & <B> "Q" \'S\'', 'target': '/x?a=1&b="2"', 'extra': 7})
            + '\n\n'
            + json.dumps({'label': '', 'target': ''})
            + '\n'
        )
        second = packed(json.dumps({'label': 'Last', 'target': '/last'}))
        chunks = [first, second]
        snapshot = chunks[:]
        self.assertEqual(decode_contacts(chunks), {
            'anchors': [
                '<a href="/x?a=1&amp;b=&quot;2&quot;">A &amp; &lt;B&gt; &quot;Q&quot; &#x27;S&#x27;</a>',
                '<a href=""></a>',
                '<a href="/last">Last</a>',
            ],
            'errors': 0,
        })
        self.assertEqual(chunks, snapshot)

    def test_line_errors_do_not_discard_other_lines(self):
        text = '\n'.join([
            json.dumps({'label': 'ok', 'target': '/ok'}),
            '{bad json',
            json.dumps(['not', 'object']),
            json.dumps({'label': 'missing'}),
            json.dumps({'label': 4, 'target': '/wrong'}),
            json.dumps({'label': 'also ok', 'target': '/two'}),
        ])
        self.assertEqual(decode_contacts([packed(text)]), {
            'anchors': ['<a href="/ok">ok</a>', '<a href="/two">also ok</a>'],
            'errors': 4,
        })

    def test_bad_gzip_and_invalid_utf8_each_count_once(self):
        invalid_utf8 = gzip.compress(b'{"label":"before","target":"/x"}\n\xff', mtime=0)
        valid = packed('{"label":"good","target":"/g"}\n')
        self.assertEqual(
            decode_contacts([b'not gzip', invalid_utf8, valid]),
            {'anchors': ['<a href="/g">good</a>'], 'errors': 2},
        )

    def test_empty_and_general_iterable(self):
        self.assertEqual(decode_contacts([]), {'anchors': [], 'errors': 0})
        self.assertEqual(
            decode_contacts(iter([packed('{"label":"x","target":"y"}')])),
            {'anchors': ['<a href="y">x</a>'], 'errors': 0},
        )

    def test_invalid_container_or_element(self):
        for value in (None, 4, [b'', 'not bytes'], bytearray(b'abc'), b'abc'):
            with self.subTest(value=value):
                with self.assertRaises(ValueError):
                    decode_contacts(value)


if __name__ == '__main__':
    unittest.main()

